(()=>{
const mobile=matchMedia('(max-width:760px)');
const icon="<span class=\"lucide-icon\" data-lucide=\"message-circle\" aria-hidden=\"true\"><svg fill=\"none\" height=\"24\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" viewBox=\"0 0 24 24\" width=\"24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M7.9 20A9 9 0 1 0 4 16.1L2 22Z\"></path></svg></span>";
const button=document.createElement('button');button.className='mobile-talk-trigger';button.innerHTML='<span class="kdek-chat-placeholder" aria-hidden="true"></span><span>มาพูดคุยกันครับ</span>';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-controls','mobileTalkDialog');
const dialog=document.createElement('dialog');dialog.id='mobileTalkDialog';dialog.className='mobile-talk-dialog';dialog.setAttribute('aria-labelledby','mobileTalkTitle');dialog.innerHTML='<button class="talk-close" aria-label="ปิดหน้าติดต่อ" autofocus><span class="lucide-icon" data-lucide="x" aria-hidden="true"><svg fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></svg></span></button><h2 id="mobileTalkTitle">มาพูดคุยกันครับ</h2><p>มีไอเดียอยากทำให้เป็นจริง หรือสนใจร่วมงานกับเรา เริ่มพูดคุยกันได้เลยครับ</p><div class="talk-actions"><a href="mailto:kodiakeclipsekage@gmail.com">ส่งอีเมลถึงเรา '+icon+'</a><a href="/#contact">ดูรายละเอียดการติดต่อ <span class="lucide-icon" data-lucide="arrow-up-right" aria-hidden="true"><svg fill="none" height="24" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="24" xmlns="http://www.w3.org/2000/svg"><g><path d="M7 7H17"></path><path d="M17 7V17"></path><path d="M7 17L17 7"></path></g></svg></span></a></div>';
document.body.append(button,dialog);let previousOverflow='';button.onclick=()=>{if(!mobile.matches)return;previousOverflow=document.body.style.overflow;dialog.showModal();document.body.style.overflow='hidden'};
dialog.querySelector('.talk-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;if(mobile.matches)button.focus({preventScroll:true})});dialog.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>dialog.close()));mobile.addEventListener('change',e=>{if(!e.matches&&dialog.open)dialog.close()});
})();